import clsx from 'clsx';
import { memo, useEffect, useRef } from 'react';
import { useSearchParams } from 'react-router-dom';
import { useComCodeState } from '~/entities/comcode/lib/use-comcode-state';
import { COM_CODE } from '~/entities/comcode/model/constants';
import i18n from '~/shared/i18n/i18n';

export const FilterList = memo(function FilterList() {
  const [searchParams, setSearchParams] = useSearchParams();
  const walletDetailSe = searchParams.get('walletDetailSe') || '';
  const { comCode } = useComCodeState(COM_CODE.TRANSACTION_TYPE);

  const refs = useRef<(HTMLButtonElement | null)[]>([]);

  const onFilterClick = (codeValue: string) => () => {
    setSearchParams((prev) => {
      const newParams = new URLSearchParams(prev);
      if (codeValue) {
        newParams.set('walletDetailSe', codeValue);
      } else {
        newParams.delete('walletDetailSe');
      }
      return newParams;
    });
  };

  useEffect(() => {
    const index = walletDetailSe ? Number(walletDetailSe) : 0;
    if (refs.current[index]) {
      refs.current[index]?.scrollIntoView({
        behavior: 'smooth',
        inline: 'center',
        block: 'nearest',
      });
    }
  }, [walletDetailSe]);

  return (
    <>
      <button
        ref={(el) => (refs.current[0] = el)}
        type="button"
        className={clsx('btn-wallet-detail-filter', { active: walletDetailSe === '' })}
        onClick={onFilterClick('')}
      >
        <span className="wallet-detail-filter">{i18n.t('total')}</span>
      </button>
      {comCode?.tbSysCodeValueList
        ?.filter((item) => item.useYn)
        ?.map((code) => (
          <button
            ref={(el) => {
              if (code.cdValue) {
                refs.current[Number(code.cdValue)] = el;
              }
            }}
            data-code-value={code.cdValue}
            type="button"
            className={clsx('btn-wallet-detail-filter', { active: code.cdValue === walletDetailSe })}
            onClick={onFilterClick(code.cdValue?.toString() ?? '')}
            key={code.cdValue}
          >
            <span className="wallet-detail-filter">{code.cdValueNm}</span>
          </button>
        ))}
    </>
  );
});
