import { memo, useState, useCallback, useRef } from 'react';
import { useWalletSearchParams } from '~/entities/wallet/lib/use-wallet-search-params';
import { BottomSheet } from '~/shared/ui/bottom-sheets/bottom-sheet';

const MAX_LENGTH = 14;

export const SearchInput = memo(function SearchInput() {
  const { updateSearchParams } = useWalletSearchParams();
  const [isSheetOpen, setIsSheetOpen] = useState(false);
  const [searchText, setSearchText] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  const handleOpen = useCallback(() => {
    setIsSheetOpen(true);
    setTimeout(() => inputRef.current?.focus(), 100);
  }, []);

  const handleClose = useCallback(() => {
    setIsSheetOpen(false);
  }, []);

  const handleConfirm = useCallback(() => {
    updateSearchParams({
      text: searchText.trim() || null,
      vouchId: null,
    });
    setIsSheetOpen(false);
  }, [searchText, updateSearchParams]);

  const handleKeyDown = (event: React.KeyboardEvent) => {
    if (event.key === 'Enter') {
      handleConfirm();
    }
  };

  return (
    <>
      <button aria-label="검색하기" className="btn-wallet-detail-search" onClick={handleOpen}>
        <i aria-hidden="true" className="icon-wallet-detail-search"></i>
      </button>
      <BottomSheet open={isSheetOpen} onClose={handleClose} title="검색">
        <div className="bottom-sheet-content">
          <div className="search-input-wrapper">
            <div className="input-field">
              <input
                type="text"
                className="form-input"
                value={searchText}
                onChange={(e) => setSearchText(e.target.value)}
                placeholder="사용처, 사람, 은행명 검색"
                maxLength={MAX_LENGTH}
                ref={inputRef}
                enterKeyHint="search"
                onKeyDown={handleKeyDown}
              />
            </div>
            <div className="input-caption-message">
              <i className="icon-caption-info" aria-hidden="true"></i>
              <span>14자 이내로 입력해주세요.</span>
            </div>
          </div>
        </div>
        <div className="bottom-sheet-footer">
          <button type="button" className="btn-sheet-confirm" onClick={handleConfirm}>
            확인
          </button>
        </div>
      </BottomSheet>
    </>
  );
});
